import json,glob,os,re
# compare logged critic/rewards/mean per step with dump mean
rows=[]
for ln in open("/tmp/clean.log",errors="replace"):
    ln=re.sub(r'^\(TaskRunner pid=\d+\)','',ln).strip()
    if ln.startswith("step:") and " - " in ln:
        d=dict()
        for p in ln.split("step:",1)[1].split(" - "):
            if ":" in p:
                k,v=p.split(":",1); d[k.strip()]=v.strip()
        rows.append(d)
by={int(float(r["training/global_step"])):r for r in rows if "training/global_step" in r}
bad=[]
for f in sorted(glob.glob("rollout_data/*.jsonl"), key=lambda p:int(os.path.basename(p).split(".")[0])):
