import pyarrow.parquet as pq, json, re, collections
def norm(s): return " ".join(str(s).split())
def pairs_from_prompt(p):
    m=re.search(r"(?:\nExamples\n|-----Examples-----)(.*?)(?:\n\\nUse Standard Input format|\Z)", p, re.S)
    if not m: return []
    body=m.group(1)
    out=[]
    for ch in re.split(r"\n+Input\n+", body)[1:]:
        parts=re.split(r"\n+Output\n+", ch, maxsplit=1)
        if len(parts)==2:
            out.append((parts[0].split("\n\n\n")[0], parts[1].split("\n\n\n")[0]))
    return [(norm(a),norm(b)) for a,b in out]
for name in ["train","test"]:
    rows=pq.read_table(f"taco_verl/{name}.parquet").to_pylist()
    checked=0; pair_ok=0; pair_bad=0; dup_in=0; dup_conf=0; uniq_out=0
    bad_ids=[]
    for r in rows:
        g=json.loads(r["reward_model"]["ground_truth"])
        ins=[norm(x) for x in g["inputs"]]; outs=[norm(x) for x in g["outputs"]]
        # duplicate inputs with conflicting outputs
        d=collections.defaultdict(set)
        for i,o in zip(ins,outs): d[i].add(o)
        if len(ins)!=len(set(ins)): dup_in+=1
        if any(len(v)>1 for v in d.values()): dup_conf+=1
        ex=pairs_from_prompt(r["prompt"][0]["content"])
        for ei,eo in ex:
            if ei in d:
                checked+=1
                if eo in d[ei]: pair_ok+=1
                else:
                    pair_bad+=1
                    if len(bad_ids)<5: bad_ids.append((r["extra_info"]["problem_id"], ei[:40], eo[:40], list(d[ei])[:1]))
    print(name,"rows",len(rows),"| example pairs checked",checked,"pair ok",pair_ok,"PAIR MISMATCH",pair_bad)
    print("   rows w/ duplicate inputs",dup_in,"rows w/ CONFLICTING outputs for same input",dup_conf)
    for b in bad_ids: print("    bad:",b)
